package com.hfr.inventory.gui;
import java.util.*; import com.hfr.packet.PacketDispatcher; import com.hfr.packet.client.XFMenuDataRequestPacket; import com.hfr.xfgui.*; import com.hfr.xfgui.XFCommandArgument.Type; import net.minecraft.client.*; import net.minecraft.client.gui.*; import net.minecraft.util.*; import org.lwjgl.input.Mouse; import cpw.mods.fml.relauncher.*;
@SideOnly(Side.CLIENT) public class GUIXenofactionsMenu extends GuiScreen implements GuiYesNoCallback { private static XFMenuData data=new XFMenuData(); private static boolean pending; private GuiTextField search; private final Map<String,GuiTextField> fields=new HashMap<String,GuiTextField>(); private XFCommandDefinition.Category cat=XFCommandDefinition.Category.FACTION; private XFCommandDefinition selected; private int scroll; private String validation="";
 public static void requestAndOpen(){Minecraft mc=Minecraft.getMinecraft(); if(mc.theWorld!=null&&mc.thePlayer!=null&&mc.currentScreen==null){pending=true; PacketDispatcher.wrapper.sendToServer(new XFMenuDataRequestPacket()); mc.displayGuiScreen(new GUIXenofactionsMenu());}}
 public static void receiveMenuData(XFMenuData d){data=d==null?new XFMenuData():d; pending=false; if(Minecraft.getMinecraft().currentScreen instanceof GUIXenofactionsMenu)((GUIXenofactionsMenu)Minecraft.getMinecraft().currentScreen).initGui();}
 public boolean doesGuiPauseGame(){return false;} public void initGui(){buttonList.clear(); fields.clear(); if(search==null) search=new GuiTextField(fontRendererObj,8,26,140,18); else search.xPosition=8; search.yPosition=26; search.width=140; int x=8,y=50,id=100; for(XFCommandDefinition.Category c:XFCommandDefinition.Category.values()){buttonList.add(new GuiButton(id++,x,y,70,18,loc("xf.category."+c.name().toLowerCase()))); if(id%2==0)x=82; else{x=8;y+=20;}} int by=height-24; buttonList.add(new GuiButton(1,width-258,by,58,20,loc("xf.menu.run"))); buttonList.add(new GuiButton(2,width-198,by,78,20,loc("xf.menu.chat"))); buttonList.add(new GuiButton(3,width-118,by,58,20,loc("xf.menu.copy"))); buttonList.add(new GuiButton(4,8,height-24,62,20,loc("xf.menu.refresh"))); buttonList.add(new GuiButton(5,74,height-24,62,20,loc("xf.menu.tutorial"))); buttonList.add(new GuiButton(6,140,height-24,80,20,loc("xf.menu.reset_tutorial"))); layoutFields(); }
 private void layoutFields(){ if(selected==null)return; int x=Math.max(160,width/2), y=104; for(int i=0;i<selected.arguments.length;i++){GuiTextField f=new GuiTextField(fontRendererObj,x,y,Math.min(180,width-x-8),18); f.setMaxStringLength(selected.arguments[i].preserveSpaces?200:64); if(selected.arguments[i].options.length==1)f.setText(selected.arguments[i].options[0]); fields.put("a"+i,f); y+=34;}}
 protected void actionPerformed(GuiButton b){ if(b.id>=100){cat=XFCommandDefinition.Category.values()[b.id-100];scroll=0;return;} if(b.id==4){pending=true;PacketDispatcher.wrapper.sendToServer(new XFMenuDataRequestPacket());return;} if(b.id==5){mc.displayGuiScreen(new GUIXenofactionsTutorial());return;} if(b.id==6){mc.displayGuiScreen(new GuiYesNo(this,"Reset Xenofactions tutorial?",GUIXenofactionsTutorial.getFlagFile().getAbsolutePath(),6));return;} if(selected==null)return; String cmd=command(); if(b.id==3){setClipboardString(selected.usage);return;} if(!validate())return; if(b.id==2){mc.displayGuiScreen(new GuiChat(cmd));return;} if(b.id==1){ if(selected.dangerous) mc.displayGuiScreen(new GuiYesNo(this,loc("xf.confirm.title"),cmd,9)); else send(cmd);} }
 public void confirmClicked(boolean ok,int id){ if(ok&&id==6)GUIXenofactionsTutorial.deleteFlag(); if(ok&&id==9)send(command()); else mc.displayGuiScreen(this);} private void send(String cmd){if(mc.thePlayer!=null)mc.thePlayer.sendChatMessage(cmd); mc.displayGuiScreen(null);} private boolean validate(){validation=""; for(int i=0;i<selected.arguments.length;i++){XFCommandArgument a=selected.arguments[i]; String v=val(i); if(a.required&&v.trim().length()==0){validation=loc("xf.validation.required");return false;} for(int j=0;j<v.length();j++){char c=v.charAt(j); if(c=='\n'||c=='\r'||Character.isISOControl(c)){validation=loc("xf.validation.control");return false;}} if(a.type==Type.INTEGER&&v.trim().length()>0)try{Integer.parseInt(v.trim());}catch(Exception e){validation=loc("xf.validation.integer");return false;} if((a.type==Type.DECIMAL)&&v.trim().length()>0)try{Double.parseDouble(v.trim());}catch(Exception e){validation=loc("xf.validation.decimal");return false;} } return true;}
 private String command(){List<String> vals=new ArrayList<String>(); if(selected!=null)for(int i=0;i<selected.arguments.length;i++){XFCommandArgument a=selected.arguments[i];String v=val(i); if(!a.preserveSpaces)v=v.trim(); if(v.length()>0)vals.add(v);} return selected==null?"":selected.buildCommand(vals);} private String val(int i){GuiTextField f=fields.get("a"+i);return f==null?"":f.getText();}
 public void updateScreen(){search.updateCursorCounter(); for(GuiTextField f:fields.values())f.updateCursorCounter();}
 protected void mouseClicked(int mx,int my,int btn){try{super.mouseClicked(mx,my,btn);}catch(Exception e){} search.mouseClicked(mx,my,btn); for(GuiTextField f:fields.values())f.mouseClicked(mx,my,btn); int x=154,y=50; List<XFCommandDefinition> list=list(); for(int i=scroll;i<list.size()&&y<height-32;i++,y+=18) if(mx>=x&&mx<Math.min(width/2-4,x+150)&&my>=y&&my<y+17){selected=list.get(i);initGui();break;}}
 protected void keyTyped(char c,int k){ if(search.isFocused())search.textboxKeyTyped(c,k); for(GuiTextField f:fields.values())if(f.isFocused())f.textboxKeyTyped(c,k); if(k==1)mc.displayGuiScreen(null);} public void handleMouseInput(){super.handleMouseInput(); int d=Mouse.getEventDWheel(); if(d!=0)scroll=Math.max(0,scroll+(d<0?1:-1));}
 public void drawScreen(int mx,int my,float f){drawDefaultBackground(); drawCenteredString(fontRendererObj,loc("xf.menu.title"),width/2,8,0xffffff); drawString(fontRendererObj,pending?loc("xf.menu.loading"):loc("xf.menu.ready"),8,8,0xa0a0a0); search.drawTextBox(); drawString(fontRendererObj,loc("xf.menu.search"),8,16,0xa0a0a0); int x=154,y=50; List<XFCommandDefinition> list=list(); for(int i=scroll;i<list.size()&&y<height-32;i++,y+=18){XFCommandDefinition d=list.get(i); drawRect(x,y,Math.min(width/2-4,x+150),y+17,d==selected?0x805050a0:0x80000000); drawString(fontRendererObj,loc(d.displayKey),x+3,y+5,d.dangerous?0xff8080:0xffffff);} if(selected!=null){int dx=Math.max(width/2,310); drawString(fontRendererObj,loc(selected.displayKey),dx,28,0xffff80); drawString(fontRendererObj,loc(selected.descriptionKey),dx,42,0xe0e0e0); drawString(fontRendererObj,loc("xf.menu.usage")+": "+selected.usage,dx,56,0xa0ffa0); drawString(fontRendererObj,loc("xf.menu.aliases")+": "+Arrays.toString(selected.aliases),dx,68,0xa0a0a0); drawString(fontRendererObj,loc("xf.menu.requirements")+": "+(selected.isAdmin()?loc("xf.permission.admin"):selected.factionRank==null?loc("xf.permission.none"):selected.factionRank),dx,80,0xa0a0a0); drawString(fontRendererObj,loc("xf.menu.preview")+": "+command(),dx,92,0xffffff); int yy=104; for(int i=0;i<selected.arguments.length;i++){drawString(fontRendererObj,loc(selected.arguments[i].nameKey),dx,yy-10,0xa0a0a0); GuiTextField gf=fields.get("a"+i); if(gf!=null)gf.drawTextBox(); yy+=34;} if(validation.length()>0)drawString(fontRendererObj,validation,dx,height-36,0xff8080);} super.drawScreen(mx,my,f);} private List<XFCommandDefinition> list(){String q=search==null?"":search.getText().toLowerCase();List<XFCommandDefinition> r=new ArrayList<XFCommandDefinition>(); for(XFCommandDefinition d:XFCommandCatalog.getCommands()){ if(d.category!=cat)continue; if(d.isAdmin()&&!data.operator)continue; if("tdm".equals(d.configRequirement)&&!data.tdmEnabled)continue; String hay=(loc(d.displayKey)+" "+loc(d.descriptionKey)+" "+d.usage+" "+Arrays.toString(d.aliases)).toLowerCase(); if(q.length()==0||hay.contains(q))r.add(d);} return r;} private static String loc(String k){String s=StatCollector.translateToLocal(k);return s==null?k:s;}}
